import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Divide, then Ground: Adapting Frame Selection to Query Types for Long-Form Video Understanding","description":"","frontmatter":{"title":"Divide, then Ground: Adapting Frame Selection to Query Types for Long-Form Video Understanding","arxiv":"2512.04000","date":"2025-12-03","authors":"Jialuo Li, Bin Li, Jiahao Li, Yan Lu","categories":"cs.AI, cs.CV, cs.LG","topics":"帧选择, 查询类型学, 训练无关框架","outline":[2,2]},"headers":[],"relativePath":"papers/2512.04000.md","filePath":"papers/2512.04000.md","lastUpdated":null}'),l={name:"papers/2512.04000.md"};function e(i,s,m,r,c,g){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="divide-then-ground-adapting-frame-selection-to-query-types-for-long-form-video-understanding" tabindex="-1">Divide, then Ground: Adapting Frame Selection to Query Types for Long-Form Video Understanding <a class="header-anchor" href="#divide-then-ground-adapting-frame-selection-to-query-types-for-long-form-video-understanding" aria-label="Permalink to &quot;Divide, then Ground: Adapting Frame Selection to Query Types for Long-Form Video Understanding&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2512.04000" target="_blank" rel="noreferrer">2512.04000</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-12-03（本页依据的是含 CVPR 2026 版正文的最新源码）</td></tr><tr><td><strong>作者</strong></td><td>Jialuo Li, Bin Li, Jiahao Li, Yan Lu</td></tr><tr><td><strong>分类</strong></td><td>cs.AI, cs.CV, cs.LG</td></tr><tr><td><strong>会议</strong></td><td>CVPR 2026</td></tr><tr><td><strong>一句话</strong></td><td>先让 LLM 把问题分成 global 与 localized 两类，global 直接均匀采样，localized 才启动「DINOv2 峰值切段取代表帧 → LMM 逐帧打 0–100 分 → 迭代均值阈值筛出高分帧 → 把对应片段并起来重新均匀采样」这条重管线。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/e-print/2512.04000</code> 取回的 LaTeX 源码（<code>main.tex</code> 加 <code>sections/</code>、<code>supp/</code> 共 16 个 tex 文件）撰写。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>近两年做 query-aware 帧选择的工作很多，它们的共同假设是：知道问题之后再选帧总比盲选好，值得为此付出搜索开销。本文直接挑战这个假设的<strong>普适性</strong>——复杂搜索机制是不是对所有类型的问题都必要？</p><p>支撑这个质疑的是一个先行的观察实验。作者在 Qwen2.5-VL-7B、InternVL3-8B、LLaVA-OneVision-7B 三个模型、MLVU / VideoMME / LongVideoBench 三个基准上扫了均匀采样的帧数，发现准确率<strong>不是单调上升</strong>的：先随帧数增加而提升，过了某个点开始下降。这个现象本身就值得解释，因为它与「上下文越长越好」的直觉相反。</p><p>作者把问题分成两类来解释：<strong>global query</strong> 需要对整段视频的整体理解（比如「哪个标题最能概括这段视频」），<strong>localized query</strong> 指向某个特定时间片段（比如「这个男的骑的是什么车」）。分类之后再看那条曲线，退化几乎全部来自 localized query——多余的帧对它们是噪声；global query 的表现则相当平稳。这条分解把「更多帧是否更好」这个笼统问题变成了一个有条件的答案，也顺手给出了一条省算力的路径。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>Token 压缩</strong>这一路（Chat-UniVi、MovieChat 的 memory bank、LongVU 的时间冗余削减、VideoChat-Flash 的层次压缩）在效率上有优势，但过度概括会丢细粒度视觉细节，而且与查询高度相关的片段可能一并被压掉。</p><p><strong>查询式帧选择</strong>这一路（BOLT、AKS、FrameVoyager、MDP³、VideoAgent、T*、Q-Frame）通常是三步：均匀采样候选帧或片段、用 CLIPScore 或检测器或学到的模型打相关性分、按分数选帧。论文对每一步都有具体批评：候选采样在信息稀疏与计算负担之间平衡得不好；CLIPScore 这类度量在复杂推理场景下不可靠，只做表层特征匹配且受限于固定词表；选出的帧时间上过于稀疏，丢掉了连续片段里的细粒度信息。</p><p>表 1 里给出的经验证据更有力：AKS 与 Q-Frame 在帧数变大时会<strong>掉到均匀采样以下</strong>。Qwen2.5-VL-7B 在 128 帧时，两者在 LongVideoBench 上都比均匀采样低 1 到 2 个点（AKS 60.36、Q-Frame 59.76 对 UNI 61.86）。这一条是本文最有说服力的立论支撑：既有方法的收益在帧预算变大后会消失甚至反向。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是发现均匀采样的帧数—精度曲线非单调，这本身就说明「往上下文里塞更多帧」有代价。第二步是找这个代价的来源，把问题按类型拆开，发现退化集中在 localized query 上。第三步的推论是对称的：既然 global query 对帧数不敏感，那么对它们做昂贵的搜索是在花钱买不到的东西；既然 localized query 对无关帧敏感，那么对它们做搜索的收益最大。这就构成了一个分流的理由。</p><p>第四步是设计 localized 那一条支路。候选帧不能靠固定 fps 或固定帧数，因为长短视频的信息密度差异极大；改成按内容自适应——DINOv2 逐帧特征距离序列上的峰值就是场景切换点，取每段中点做代表帧，代表帧数量自然随视频复杂度变化。第五步是打分，既然 CLIPScore 不可靠，就直接用 LMM 自己打，代价是每帧一次前向。第六步是选帧：Top-K 需要一个固定的 K，而不同视频里高分帧的数量本来就不一样，于是设计一个无参数的迭代均值阈值。第七步是把选中的代表帧还原成连续片段并合并，避免时间上过于稀疏。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>不是所有问题都需要搜索。要求整体理解的问题，均匀采样提供的时间覆盖已经是最优解，再复杂的选帧也只是把同样的信息重排一遍；指向特定片段的问题才会被无关帧污染，也才配得上搜索的开销。先花一次 LLM 调用把问题分类，就能把昂贵的管线只用在需要它的那一半上。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>第一步：查询类型识别。</strong> 用一个 LLM（主实验用 Qwen3-Next-80B-A3B-Instruct）配 chain-of-thought 提示，让它先分析问题意图、再推测视频体裁、再识别具体指称对象，最后判定 global 还是 localized。global 直接走均匀采样，流程结束。</p><p><strong>第二步：Content-Adaptive Frame Selection（CAFS）。</strong> 视频按 2 fps 抽出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 帧，用 DINOv2 提特征，算相邻帧距离 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0418em;vertical-align:-0.2918em;"></span><span class="mord"><span class="mord mathrm">sim</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:-0.0785em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:-0.0785em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2025em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2918em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>。满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 且 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9028em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 且 prominence 大于 0.1 的位置记为有效峰值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span>，作为分段点。每段取中点帧作为代表帧（论文称 R-Frame），索引为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1467em;vertical-align:-0.3948em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span><span class="mclose">}</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">/2</span><span class="mclose">}</span></span></span></span>。</p><p><strong>第三步：Reward Assignment。</strong> 把每个代表帧连同问题、视频时长、该帧时间戳一起送进 LMM，让它先描述画面中与问题相关的元素，再给出 0 到 100 的分数。评分维度有两个：该帧对回答问题的直接有用性，以及<strong>该帧是否暗示其相邻帧可能含有补充信息</strong>。第二个维度是为「为什么」「怎么样」这类无法靠单帧回答的问题设计的。</p><p><strong>第四步：Video Refinement。</strong> 无参数的迭代筛选：算当前分数集的均值 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8833em;"></span><span class="mord overline"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8833em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span><span style="top:-3.8033em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span></span></span></span></span></span></span>，令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1467em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mop">max</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1333em;vertical-align:-0.25em;"></span><span class="mord overline"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8833em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span><span style="top:-3.8033em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mclose">)</span></span></span></span>；取正值索引集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span>，若与上一轮完全相同则终止，否则以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1467em;vertical-align:-0.3948em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span><span class="mclose">}</span></span></span></span> 为新分数集重来。终止后保留分数为正的代表帧。然后做片段合并：对每个保留的代表帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1467em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>，取其所在段 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>，并向两侧各扩 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span></span></span></span> 个代表帧，得到区间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mbin mtight">−</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">]</span></span></span></span>，所有区间取并集构成精修后的视频。最后从精修视频里均匀采样得到最终输入帧。</p><p><strong>实现细节</strong>：基座 LMM 为 Qwen2.5-VL-7B 与 32B，每帧 56 个 token，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>，8 张 A100，在 LMMs-Eval 框架下评测，查询识别与打分阶段用 vLLM 加速。VideoMME 只用 medium 与 long 两档，全程不用字幕。</p><p><strong>一个具体例子</strong>：问「视频里那辆车是什么牌子」是 localized query，CAFS 会把视频切成若干视觉同质段，LMM 给含车的那几段的代表帧打高分，迭代阈值把它们筛出来，扩窗合并成一小段连续视频，最终 32 帧全部落在这一小段里，车标因此有机会被看清。问「这段视频主要讲什么」则是 global query，直接在全片上均匀取 32 帧。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化很轻。核心的一步是那个无参数的迭代阈值：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.185em;vertical-align:-0.3831em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8019em;"><span style="top:-2.453em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2333em;vertical-align:-0.35em;"></span><span class="mord overline"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8833em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span><span style="top:-3.8033em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∀</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8389em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span></span></span></span></span></p><p>反复迭代直到正值索引集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1467em;vertical-align:-0.3948em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-2.4413em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0</span><span class="mclose">}</span></span></span></span> 稳定。这个过程的性质值得说清楚：每一轮都把当前存活集合的均值减掉，因此每一轮至少剔除掉分数低于当前均值的那些帧，集合单调收缩，必然收敛。它等价于一个「反复取高于均值的部分」的操作，最终保留的是分数分布中一个由数据自身决定的上尾，而不是一个人为指定的 Top-K。当分数分布接近均匀时它收敛得慢、保留得多；当分布高度尖峰时它迅速收敛到少数几帧。这正是「不同视频里高分帧数量本来就不同」这个观察所要求的行为。</p><p>评估 CAFS 质量的两个指标也是形式化的。Localized Coverage 衡量每个代表帧对其局部时间上下文的代表性，取代表帧与其周围均匀采样的四个邻帧的平均相似度；Global Coverage 衡量代表帧集合对全片的覆盖，随机采 200 帧，对每帧取它与任一代表帧的最大相似度再平均：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">GlC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.6431em;vertical-align:-1.3217em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8557em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">x</span><span class="mrel mtight">∈</span><span class="mord mathcal mtight" style="margin-right:0.1464em;">X</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3217em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.309em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">∈</span><span class="mopen mtight">[</span><span class="mord mtight">1</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span><span class="mclose mtight">]</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.966em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">sim</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:-0.0785em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">.</span></span></span></span></span></p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：相对已有方法与均匀采样如何？</strong> 表 1 覆盖 8 到 256 帧。以 Qwen2.5-VL-32B、32 帧为例（MLVU / LVB / VideoMME-Medium / VideoMME-Long）：UNI 是 61.91 / 57.89 / 57.89 / 53.33，AKS 是 66.42 / 59.31 / 59.89 / 56.00，Q-Frame 是 60.95 / 57.37 / 60.43 / 55.90，DIG 是 70.69 / 61.86 / 60.87 / 57.76。7B 上 32 帧，MLVU 从 59.52 提到 67.20（+7.68）。</p><p>正文写「32 帧时在 LongVideoBench 上比均匀采样高 4.51」，但表里 7B 的对应数字是 56.92 → 60.43，差值 3.51；32B 是 57.89 → 61.86，差值 3.97。两个都不是 4.51。</p><p><strong>问题二：帧数放大后还成立吗？</strong> 这是本文最想证明的一点。7B 在 256 帧时，MLVU 从 69.15 提到 72.46、LVB 从 61.48 提到 64.62；而 AKS 在 LVB 上是 61.03、在 VideoMME-Long 上是 55.11，两项都低于均匀采样。表格用红底标出了低于均匀采样的格子，Q-Frame 与 AKS 各有多处，说明作者对这条线的关注是真诚的。</p><p>不过 DIG 自己也吃了红底：32B 在 8 帧与 16 帧的 VideoMME-Long 上分别是 51.21 与 52.18，均匀采样是 51.56 与 53.33。7B 在 8 帧的 VideoMME-Long 上是 46.88，Q-Frame 是 49.21（该格最优）。所以「consistently outperforms existing baselines」这个措辞对短帧预算下的长视频段不成立，作者在正文里的表述是「across all tested LMMs and most input frame configurations」，比摘要谨慎。</p><p><strong>问题三：分流这一步本身对不对？</strong> 图 8 分别在 global 与 localized 两类问题上比较均匀采样与完整管线：global 上均匀采样与管线相当甚至偶尔更好，localized 上管线一致更优。这正是分流设计的直接依据。</p><p><strong>问题四：CAFS 值多少？</strong> 图 9 用 GlC / LoC 两个指标在同等平均帧数下比较 UNI、FPS、CAFS，CAFS 在 10 分钟以上的视频上优势最明显。图 10 把管线里的 CAFS 换成均匀采样，CAFS 一致更好，且帧数越多差距越大。</p><p><strong>问题五：打分器用 LMM 还是 CLIPScore？</strong> 表 12 里 LMM 打分在多数格子上优于 CLIPScore，且 32B 打分优于 7B 打分。例如 7B 作基座、16 帧时，CLIPScore / 7B 打分 / 32B 打分在 MLVU 上分别是 62.2 / 64.0 / 64.0，在 LVB 上是 54.3 / 57.9 / 59.2。作者据此指出打分器可以与推理骨干解耦。</p><p><strong>问题六：扩窗大小？</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">4</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">8</span><span class="mclose">}</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 最差（尤其在 LongVideoBench 上），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8</span></span></span></span> 也退化，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mord mathnormal">e</span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> 最优。</p><p><strong>问题七：查询分类器准不准？</strong> 表 13 是全文最该被仔细读的一张。人工标注给出的分布是：MLVU 462 个 global / 1708 个 localized（直接沿用其任务分类），LongVideoBench 全部是 localized，VideoMME 由人工按标准流程多数投票标出 479 个 global / 2221 个 localized。四个 LLM 的分类准确率里，主实验采用的 Qwen3-Next-80B-A3B-Instruct 在 MLVU 上 LQ 87.02 / <strong>GQ 38.26</strong> / 总体 78.52，在 VideoMME 上 LQ 89.13 / GQ 65.76 / 总体 83.90。其他模型的 GQ 更低：Llama-3.1-8B 是 24.01 与 34.24，DeepSeek-R1-Distill-Qwen-32B 是 26.38 与 52.85；只有 GPT-OSS-20B 的 GQ 达到 74.93 与 69.97。</p><p><strong>问题八：省了多少算力？</strong> 表 16（分钟）：把管线无差别地用在所有问题上 vs 走分流，MLVU 从 295.7 降到 256.3（−13.3%，localized 占 82.8%），VideoMME 从 384.2 降到 307.9（−19.9%，占 77.0%），LongVideoBench 因为几乎全是 localized，反而从 134.1 升到 138.9（+3.6%）。表 15 的选帧总开销为 MLVU 256.3、LVB 138.9、VideoMME 307.9 分钟，其中 Reward Assignment 分别占 218.9 / 110.4 / 264.8；AKS 三个数据集均记为「≥720」，Q-Frame 为 122.1 / 34.5 / 94.2。表 14 给出同一 7B 模型在 32 帧下的推理时间为 MLVU 9.3、LVB 4.3、VideoMME 8.7 分钟。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：均匀采样的帧数—精度曲线非单调，退化几乎全部来自 localized query，这条分解本身就是一个可复用的诊断工具；据此把问题分成 global 与 localized 两类分流处理，是一个成本敏感的正确直觉；CAFS 用 DINOv2 距离峰值自适应地决定候选帧数量，比固定 fps 或固定帧数更贴合视频复杂度；用 LMM 自身打分优于 CLIPScore，且打分器可以与推理骨干解耦，用更大的模型打分能进一步提升；但分流的关键前提——查询分类器——在 global 类上的准确率只有 38.26%（MLVU）与 65.76%（VideoMME），实测省下的算力只有 13.3% 与 19.9%，在 LongVideoBench 上还倒亏 3.6%。</p><p><strong>3 句话版</strong>：先分类问题再决定要不要搜索，把选帧的成本花在真正需要的那一半上。在 8 到 256 帧的全区间上稳住了相对均匀采样的增益，而 AKS 与 Q-Frame 在高帧数下会掉到均匀采样以下。代价是选帧开销约为 LMM 推理的三十倍，且其中 85% 花在逐帧调 LMM 打分上。</p><p><strong>1 句话版</strong>：不是所有问题都值得搜索，先判断问题类型，再决定用不用昂贵的选帧管线。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>失败代价最大的一条是：<strong>LLM 能够可靠地把问题分成 global 与 localized 两类</strong>。整篇论文的题目、动机、以及唯一区别于其他选帧工作的贡献都建立在这个分流上；分流的价值全部来自「global 那一半不必付搜索代价」。</p><p>论文自己的表 13 显示这个前提在最关键的那一半上不成立。主实验采用的 Qwen3-Next-80B-A3B-Instruct 在 MLVU 的 global query 上准确率是 <strong>38.26%</strong>——对一个二分类任务而言这低于随机猜测。也就是说 MLVU 那 462 个 global query 里有六成被误判成 localized，被送进了昂贵的管线。VideoMME 上的 65.76% 略好，但也意味着三分之一的 global query 被误路由。</p><p>作者对此的回应是：GQ 分类错误的影响可以忽略，因为对 global query 而言两条路径的性能差异本来就很小，误判只带来「minor computational overhead」，真正重要的是 LQ 准确率（几乎所有 LLM 都超过 90%）。这个论证在<strong>精度</strong>维度上是自洽的，在<strong>效率</strong>维度上却把结论抽空了：既然分流的全部意义是省算力，而 global 那一半有六成没被识别出来，那么省下的算力自然只剩表 16 里那 13.3% 与 19.9%。论文的核心问题是「复杂搜索是不是普遍必要」，它给出的答案是「不必要」，但它自己的实现只兑现了这个答案的一小部分。</p><p>更要紧的是，<strong>这个假设在精度维度上到底成不成立，论文其实没有验证</strong>。表 16 只报了「w/o QI」（把管线无差别地用在所有问题上）的<strong>耗时</strong>，没有报它的<strong>准确率</strong>。这一格恰恰是最关键的消融：如果 w/o QI 的准确率与 DIG 相同甚至更高，那么查询识别模块在精度上毫无贡献，它的全部价值就是那 13.3% 到 19.9% 的算力，而它自己还要花 11.3 到 11.6 分钟。图 8 只在人工标注的类型上分别比较了两条路径，这不等于端到端地比较「用分类器」与「不用分类器」。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需要跑推理：</p><ol><li>在 MLVU 与 VideoMME 上用 Qwen2.5-VL-7B、32 帧，跑四种配置的<strong>准确率</strong>：(a) 纯均匀采样；(b) DIG（LLM 分类器分流）；(c) w/o QI（对所有问题都走完整管线）；(d) oracle QI（用论文提供的人工标注类型分流）。</li><li>参照点：MLVU 上 UNI 59.52、DIG 67.20；VideoMME-Medium 上 UNI 59.08、DIG 61.62。</li><li>判据： <ul><li>若 (c) ≈ (b)，则查询识别模块对精度无贡献，它的定位应当从「方法的核心」下调为「一个可选的算力优化开关」，且这个开关的收益只有 13.3%–19.9%。</li><li>若 (c) 明显低于 (b)，说明对 global query 强行走管线确实有害，那么 (d) 与 (b) 的差距就直接量化了分类器 38.26% 的 GQ 准确率造成的精度损失，这个数字目前完全未知。</li><li>把 (b) 与 (d) 的差值和 GQ 误判率放在一起，还能反推出「误判一个 global query 的平均代价」，这是论文声称可忽略但从未量化的那个量。</li></ul></li></ol><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>第一击直接引用一篇同期同方向的工作。EFS（arXiv 2603.00983）做了一个几乎相同的实验：用 CoT router 把问题分成具体的与概括的，概括的退回均匀采样，其余走自家选帧管线，称为「part EFS」。结果是 part EFS 在三个基准上<strong>一致低于</strong>全量 EFS：VideoMME 62.5（−1.5）、LongVideoBench 60.7（−0.6）、MLVU 68.6（−0.4）。EFS 据此得出的结论与本文相反——对概括类问题退回均匀采样是有害的，结构化选帧即便对 information synopsis 类问题也有益。两篇论文用的基准重叠、骨干模型同为 7B 级、分类方式都是 LLM 提示，结论却相反。这构成了对本文核心主张最直接的外部反例，而解决它需要的正是 §10 里那个缺失的 (c) 配置。</p><p>第二击针对<strong>效率叙述</strong>。表 15 里 AKS 的开销在三个数据集上全部记为「≥720」分钟，这是一个截断的下界，不是测量值。用一个截断下界去支撑「reducing computational overhead by an order of magnitude」的说法，读者无法验证倍数。同时 DIG 自己的开销并不小：VideoMME 上选帧 307.9 分钟，而同数据集 32 帧的 LMM 推理只要 8.7 分钟，比例约 35 : 1；其中 Reward Assignment 一项就占 264.8 分钟（86%），因为它要对每个代表帧调一次 LMM 并生成一段描述加一个分数。图 12 用 FLOPs 做的对比只画到「DIG 在超过 720 TFLOPs 后开始超过均匀采样 62.5% 的峰值」，但没有把打分阶段的 LMM 前向计入同一坐标系。一个干净的反例实验是：把 DIG 消耗的总 FLOPs（含打分）折算成均匀采样能承受的帧数，直接跑那个帧数的均匀采样。鉴于论文自己证明了均匀采样在 LVB 上会饱和于 62.5%，这个对照大概率对 DIG 有利——但它必须被做出来，否则「效率」这个卖点缺少同预算的对照。</p><p>第三击是几处内部不一致。其一，正文写 32 帧时 7B 在 LongVideoBench 上相对均匀采样提升 4.51，表 1 里对应的差值是 3.51（56.92 → 60.43）。其二，摘要与引言写「consistently outperforms existing baselines」，而表 1 里 DIG 自己在 32B、8 帧与 16 帧的 VideoMME-Long 上被标了红底（51.21 对 UNI 51.56，52.18 对 UNI 53.33），7B、8 帧的 VideoMME-Long 上也输给 Q-Frame（46.88 对 49.21）。这些红底是作者自己标的，说明表格是诚实的，问题出在摘要的措辞收得不够紧。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：global 与 localized 是一个<strong>二元且静态</strong>的划分，而且必须在看到视频之前、仅凭问题文本做出。表 13 里 GQ 准确率只有 38% 这件事本身就在提示：这个类型可能根本不是问题文本的属性。「视频里出现过几次讲师」在一个只有一个场景的视频里是 global 的，在一个有四十个场景的视频里是 localized 的——类型是问题与视频的<strong>联合</strong>属性。</p><p><strong>新的 framing</strong>：不要预测类型，而是预测<strong>证据的时间分布</strong>。把选帧重述为一个序贯决策问题：先用极小预算（比如 8 帧）拿到 LMM 的答案 logits，据此估计「答案所需证据在时间轴上是集中的还是弥散的」，再决定后续预算是继续摊开还是收拢到某个区间。这样 global/localized 就从一个需要提前分类的离散标签，变成一个随观测更新的连续量，而且它天然是视频相关的。</p><p><strong>可借鉴的邻域工具</strong>：序贯假设检验（尤其是 SPRT 这类可以随时停止的框架）给出了「在观测到足够证据前不做决定」的标准形式；bandit 里的 successive halving 则提供了在多个时间区间之间分配采样预算的现成算法——把视频的每个 CAFS 段当作一个 arm，把 LMM 在该段上的答案置信度当作 reward，预算逐轮减半地收拢。</p><p><strong>第一个实验</strong>：在 MLVU 上取人工标注的 462 个 global 与 1708 个 localized query，用 8 帧的答案 logits 熵作为「证据弥散度」的代理，画出两类问题的熵分布。如果两个分布分离得比 LLM 文本分类器更好（表 13 给了 38.26% 这个可以直接对比的基线），就证明「看一眼视频再判断」比「只看问题文本判断」更可靠，分流这一步应当从预处理挪到推理循环内部。接着再比较三种预算分配策略在同等总 FLOPs 下的准确率：固定均匀、DIG 的分流、以及基于熵的序贯收拢。这条路线的好处是它把本文最脆弱的那个模块（离线的二元分类器）替换成了一个与视频有关、且不需要额外标注的信号。</p>',62)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
